parameters.jsCode:
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
const match = raw.match(/\{[\s\S]*\}/);
let analysis = {};
try { analysis = JSON.parse(match?.[0] || '{}'); } catch (_) {}

const niche = (() => {
  try { return JSON.parse($('Execute Workflow Trigger').first().json.trendReport || '{}').niche; } catch(_) { return ''; }
})();

return [{ json: { niche, ...analysis } }];
